  "Norwich", "Nottingham", "Oxford", "Peterborough", "Plymouth", "Portsmouth", "Preston", "Ripon",
  "Salford", "Salisbury", "Sheffield", "Southampton", "Southend-on-Sea", "St Albans", "Stoke on Trent",
  "Sunderland", "Truro", "Wakefield", "Wells", "Westminster", "Winchester", "Wolverhampton", "Worcester", "York",

  // Northern Ireland
  "Armagh", "Bangor", "Belfast", "Lisburn", "Londonderry", "Newry",

  // Scotland
  "Aberdeen", "Dundee", "Dunfermline", "Edinburgh", "Glasgow", "Inverness", "Perth", "Stirling",

  // Wales
  "Bangor", "Cardiff", "Newport", "St Asaph", "St Davids", "Swansea", "Wrexham"
];

const topJewelleryHubs = [
  "Birmingham", // Jewellery Quarter
  "London", // Hatton Garden & Mayfair
  "Manchester",
  "Edinburgh",
  "Glasgow",
  "Leeds",
  "Bristol",
  "Bath",
  "York",
  "Chester",
  "Brighton & Hove",
  "Cardiff",
  "Belfast"
];

let targetList = [];
if (rawMode === 'single_city' || rawMode === 'single') {
  targetList = [config.location || 'Birmingham'];
} else if (rawMode === 'top_jewellery_hubs' || rawMode === 'top_hubs' || rawMode === 'hubs') {
  targetList = topJewelleryHubs;
} else {
  // Default: All 76 UK Cities (covers 'all', 'all_uk_cities', 'all_cities', etc.)
  targetList = allUkCities;
}

return targetList.map(city => ({
  json: {
    ...config,
    location: city,
    target_city: city
  }
}));

