  const geoData = Array.isArray(geoItem) ? geoItem[0] : geoItem;
  const payload = {
    q: `${cityItem.query || 'bespoke jewellers'} in ${cityItem.location}`,
    gl: 'gb',
    hl: 'en'
  };
  if (geoData && geoData.lat && geoData.lon) {
    payload.ll = `@${geoData.lat},${geoData.lon},13z`;
  }
  return JSON.stringify(payload);
