/**
 * UNIVERSAL MULTI-NICHE QUALITY GATE & LEAD VERIFIER
 * Works automatically for ANY niche (Jewellers, Roofers, Trades, Accountants, Clinics, etc.)
 * 1. Automatically adapts pitches, offers, and prototype links based on your 'query'
 * 2. Rejects corporate switchboards (0800, 0845, 0870, 0300) so you only reach owners
 * 3. Normalizes phones to UK standard (+44...)
 * 4. Generates 1-click WhatsApp direct links for UK mobiles (+447...)
 * 5. Adds Verification Status honesty flags (Verified site vs Unverified)
 * 6. Deduplicates across the batch
 */

const items = $input.all();
const config = $('Edit Fields').first().json || {};
const query = (config.query || 'bespoke jewellers').trim();
const minReviews = Number(config.min_reviews || 1);
const onlyNoWebsite = Boolean(config.only_no_website === true);

function detectTradeInfo(q, category, name) {
  const text = `${q} ${category || ''} ${name || ''}`.toLowerCase();

  if (text.includes('jewel') || text.includes('diamond') || text.includes('gold') || text.includes('ring') || text.includes('gem') || text.includes('atelier') || text.includes('watch')) {
    return {
      trade: 'Jeweller',
      leadType: 'jewellery',
      serviceInterested: 'Interactive 3D Digital Atelier & Bespoke Commission Portal',
      isJewellery: true
    };
  }
  if (text.includes('roof')) {
    return {
      trade: 'Roofer',
      leadType: 'tradesperson',
      serviceInterested: 'High-Converting Digital Storefront & Speed-to-Lead Automation',
      isJewellery: false
    };
  }
  if (text.includes('plumb')) {
    return {
      trade: 'Plumber',
      leadType: 'tradesperson',
      serviceInterested: 'Emergency Speed-to-Lead Automation & Online Booking',
      isJewellery: false
    };
  }
  if (text.includes('electr')) {
    return {
      trade: 'Electrician',
      leadType: 'tradesperson',
      serviceInterested: 'High-Converting Digital Storefront & Speed-to-Lead Automation',
      isJewellery: false
    };
  }

  // Any other local niche (e.g. Accountants, Dentists, Architects)
  const cleanQ = q.replace(/[^a-zA-Z\s]/g, '').trim();
  const titleQ = cleanQ ? (cleanQ.charAt(0).toUpperCase() + cleanQ.slice(1)) : 'Local Business';
  return {
    trade: titleQ,
    leadType: 'local',
    serviceInterested: 'Digital Storefront & Speed-to-Lead Automation',
    isJewellery: false
  };
}

const validatedLeads = [];
const seenPhones = new Set();
const seenNames = new Set();

for (const item of items) {
  const place = item.json || {};
  const businessName = (place.title || place.name || '').trim();
  const rawPhone = (place.phoneNumber || place.phone || '').trim();
  const rawWebsite = (place.website || '').trim();
  const rating = Number(place.rating || 0);
  const reviewsCount = Number(place.ratingCount || place.user_ratings_total || 0);
  const address = (place.address || place.formatted_address || '').trim();
  const category = place.category || place.type || '';

  if (!businessName || !rawPhone) continue;
  if (reviewsCount < minReviews) continue;

  // Reject call centers & switchboards
  const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
  if (
    cleanDigits.startsWith('0800') ||
    cleanDigits.startsWith('0808') ||
    cleanDigits.startsWith('0845') ||
    cleanDigits.startsWith('0870') ||
    cleanDigits.startsWith('0300') ||
    cleanDigits.startsWith('0345') ||
    cleanDigits.startsWith('44800') ||
    cleanDigits.startsWith('44845') ||
    cleanDigits.startsWith('44300')
  ) {
    continue;
  }

  // Normalize phone
  let formattedPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (formattedPhone.startsWith('0')) {
    formattedPhone = '+44' + formattedPhone.substring(1);
  } else if (!formattedPhone.startsWith('+44')) {
    formattedPhone = '+44' + formattedPhone.replace(/^\+/, '');
  }
  const digitsOnly = formattedPhone.replace(/[^0-9]/g, '');

  // Deduplicate across the batch
  const nameKey = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seenPhones.has(digitsOnly) || seenNames.has(nameKey)) continue;
  seenPhones.add(digitsOnly);
  seenNames.add(nameKey);

  // Classification & Verification Flag
  let hasWebsite = true;
  let classification = 'has_website';
  let verificationStatus = 'VERIFIED — Live Website Available';

  if (!rawWebsite || rawWebsite === '' || rawWebsite.toLowerCase() === 'none' || rawWebsite.toLowerCase() === 'null') {
    hasWebsite = false;
    classification = 'no_website';
    verificationStatus = 'UNVERIFIED — Google Maps only, confirm via Instagram/Search before outreach';
  } else {
    const w = rawWebsite.toLowerCase();
    if (w.includes('facebook.com') || w.includes('instagram.com') || w.includes('yell.com')) {
      hasWebsite = false;
      classification = 'social_only';
      verificationStatus = 'UNVERIFIED — Social media link only, confirm via web search';
    }
  }

  if (onlyNoWebsite && hasWebsite) continue;

  const isMobile = digitsOnly.startsWith('447');
  const channel = isMobile ? 'WhatsApp / SMS' : 'Landline / Direct Call';

  // Trade and Niche Intelligence
  const tradeInfo = detectTradeInfo(query, category, businessName);

  // Dynamic Prototype URL
  const protoUrl = tradeInfo.isJewellery
    ? `https://veyra-premium-3-d-jewellery-e-comme.vercel.app/?client=${encodeURIComponent(businessName)}`
    : `https://mercian-wealth.vercel.app/preview/demo?client=${encodeURIComponent(businessName)}&niche=${encodeURIComponent(tradeInfo.trade)}`;

  // Tailored Luxury / Professional Consultative Pitches
  let stage1Opener = '';
  let stage2Pitch = '';

  if (tradeInfo.isJewellery) {
    if (!hasWebsite) {
      stage1Opener = `Hi 👋 Came across ${businessName} on Instagram — stunning work. Had a quick search for your website to view the full collection, couldn't find one. Do you take all your bespoke commissions through WhatsApp / Instagram directly?`;
      stage2Pitch = `The pieces look exceptional. We put together a private interactive 3D concept prototype showing how ${businessName} could showcase custom rings and bespoke pieces with a dedicated online storefront: ${protoUrl} — take a look when you have a moment, no pressure at all.`;
    } else {
      stage1Opener = `Hi 👋 Came across ${businessName} — love the craftsmanship in your pieces. Had a quick look through your site, had a small question about how you showcase your bespoke commissions online if you have 30 seconds?`;
      stage2Pitch = `Loved looking through your catalogue. We noticed that high-ticket bespoke jewellery often loses that in-person luxury feel on standard mobile galleries. We built an interactive 3D concept prototype demonstrating how ${businessName}'s collection could be presented: ${protoUrl} — thought you might enjoy seeing it.`;
    }
  } else {
    // Universal local trade / service pitch
    if (!hasWebsite) {
      stage1Opener = `Hi 👋 Came across ${businessName} — noticed you don't have a website listed to showcase your completed projects and reviews. Do you take all your new enquiries through direct calls / word of mouth?`;
      stage2Pitch = `We put together an interactive digital storefront concept showing how ${businessName} could capture inbound quote requests 24/7 with zero manual back-and-forth: ${protoUrl} — take a look when you have a moment, no pressure at all.`;
    } else {
      stage1Opener = `Hi 👋 Came across ${businessName} — great reputation in the area. Had a quick question about how you manage inbound online enquiries if you have 30 seconds?`;
      stage2Pitch = `We built an interactive speed-to-lead prototype showing how ${businessName} could instantly qualify incoming project enquiries before picking up the phone: ${protoUrl} — thought you might find it interesting.`;
    }
  }

  const followUp1 = `Hey — following up on ${businessName}. No pressure at all, just wanted to check if this landed and see what you thought of the prototype.`;
  const followUpFinal = `Last one from me on this — if elevating your digital presence isn't a priority right now, that's completely fair. If it ever is, the offer stands. All the best!`;

  const waLink = isMobile ? `https://wa.me/${digitsOnly}?text=${encodeURIComponent(stage1Opener)}` : 'N/A';

  // Supabase Payload
  const supabasePayload = {
    name: 'Owner / Director',
    business_name: businessName,
    phone: formattedPhone,
    website: hasWebsite ? rawWebsite : null,
    service_interested: tradeInfo.serviceInterested,
    notes: `${address} · ★${rating} (${reviewsCount} reviews) · [${verificationStatus}]`,
    status: 'New',
    source: 'google_maps_outreach',
    lead_type: tradeInfo.leadType,
    local_business_niche: tradeInfo.trade,
    outreach_category: classification,
    outreach_stage: 'uncontacted',
    prototype_url: protoUrl,
    whatsapp_direct_url: isMobile ? waLink : null,
    scraped_metadata: {
      address: address,
      rating: rating,
      reviews_count: reviewsCount,
      trade: tradeInfo.trade,
      channel: channel,
      verification_status: verificationStatus,
      stage_1_opener: stage1Opener,
      stage_2_pitch: stage2Pitch,
      follow_up_1: followUp1,
      follow_up_final: followUpFinal,
      prototype_url: protoUrl
    }
  };

  validatedLeads.push({
    json: {
      "Business Name": businessName,
      "Phone": formattedPhone,
      "Channel": channel,
      "WhatsApp Link": waLink,
      "Reviews": reviewsCount,
      "Rating": rating,
      "Website": rawWebsite || 'None',
      "Address": address,
      "Trade": tradeInfo.trade,
      "Classification": classification,
      "Verification Status": verificationStatus,
      "Stage 1 Opener": stage1Opener,
      "Stage 2 Pitch": stage2Pitch,
      "Follow Up 1": followUp1,
      "Follow Up Final": followUpFinal,
      "Prototype URL": protoUrl,
      "Status": 'New',
      "supabase_payload": supabasePayload
    }
  });
}

return validatedLeads;

