const todayStr = now.toLocaleDateString('en-CA');

const dueLeads = [];

for (const item of items) {
  const row = item.json || {};
  const leadId = (row['Lead ID'] || '').trim();
  const name = (row['Business Name'] || 'Jeweller').trim();
  const niche = (row['Niche'] || 'Jeweller').trim();
  const phone = (row['Phone Number'] || '').trim();
  const stage = (row['Current Stage'] || 'Sourced').trim();
  const due = (row['Next Action Due'] || '').trim();
  const protoUrl = (row['Prototype URL'] || `https://veyra-premium-3-d-jewellery-e-comme.vercel.app/?client=${encodeURIComponent(name)}`).trim();
  const notes = (row['Notes'] || '').trim();

  if (!leadId || !name) continue;
  if (stage.toLowerCase() === 'won' || stage.toLowerCase() === 'lost') continue;
  if (!due || due > todayStr) continue;

  let stageBadge = '';
  let preDraftedCopy = '';
  let nextStageAction = '';
  let urgencyRank = 2;

  // Luxury Jeweller Master Sequence
  if (stage === 'Sourced') {
    stageBadge = '💎 STAGE 1 OPENER (Jeweller Review)';
    urgencyRank = 1;
    nextStageAction = 'Mark Contacted (+2d)';
    preDraftedCopy = `Hi 👋\n\nCame across ${name} — love the craftsmanship in your pieces. Had a quick search for your website to view the full collection, couldn't find one. Do you take all your bespoke commissions through WhatsApp / Instagram directly?`;
  } else if (stage === 'Contacted') {
    stageBadge = '⚡ STAGE 2 (DAY 2 BUMP)';
    urgencyRank = 1;
    nextStageAction = 'Advance to Follow-up 1 (+2d)';
    preDraftedCopy = `Hey — following up on ${name}. No pressure at all, just wanted to check if this landed.`;
  } else if (stage === 'Follow-up 1 Due') {
    stageBadge = '✨ STAGE 3 (PROTOTYPE TEASE / VALUE DROP)';
    urgencyRank = 2;
    nextStageAction = 'Advance to Prototype Follow-up (+2d)';
    preDraftedCopy = `Hey — put together an interactive 3D concept prototype demonstrating how ${name} could present bespoke pieces and rings online: ${protoUrl} — take a look when you have a moment, no pressure at all 👀`;
  } else if (stage === 'Prototype Sent') {
    stageBadge = '🎯 STAGE 4 (PROTOTYPE 48H FEEDBACK CHECK)';
    urgencyRank = 1;
    nextStageAction = 'Move to Nurture (+30d) - Stop Rule';
    preDraftedCopy = `Hey ${name} — did you have a chance to take a look at the 3D prototype (${protoUrl})? Would love to hear what you think 👀`;
  } else if (stage === 'Nurture') {
    stageBadge = '🌿 STAGE 5 (NURTURE RE-ENGAGEMENT)';
