const query = $input.first().json.query || {};
const leadId = query.id || 'Unknown';
const businessName = query.name || '';
const phone = query.phone || '';
const action = (query.action || 'sent').toLowerCase();
const currentStage = query.stage || 'Sourced';

const now = new Date();
function addDays(days) {
  const d = new Date(now);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

let newStage = currentStage;
let nextActionDue = '';
let feedbackMsg = '';

if (action === 'sent') {
  if (currentStage === 'Sourced') {
    newStage = 'Contacted';
    nextActionDue = addDays(2);
    feedbackMsg = 'Stage 1 Opener logged. Follow-up 1 automatically scheduled for ' + nextActionDue + ' (+2 days).';
  } else if (currentStage === 'Contacted') {
    newStage = 'Follow-up 1 Due';
    nextActionDue = addDays(2);
    feedbackMsg = 'Day 2 Bump logged. Value follow-up scheduled for ' + nextActionDue + ' (+2 days).';
  } else if (currentStage === 'Follow-up 1 Due') {
    newStage = 'Nurture';
    nextActionDue = addDays(7);
    feedbackMsg = 'Final value follow-up logged. Moved to Nurture for check-in on ' + nextActionDue + ' (+7 days).';
  } else if (currentStage === 'Prototype Sent') {
    newStage = 'Nurture';
    nextActionDue = addDays(30);
    feedbackMsg = 'Prototype follow-up logged. Strict 1-and-done enforced: lead moved to Nurture (+30 days).';
  } else if (currentStage === 'Nurture') {
    newStage = 'Lost';
    nextActionDue = '';
    feedbackMsg = 'Nurture check-in completed. Lead archived.';
  } else {
    newStage = 'Contacted';
    nextActionDue = addDays(2);
    feedbackMsg = 'Lead updated. Next action scheduled for ' + nextActionDue + '.';
  }
} else if (action === 'snooze') {
  nextActionDue = addDays(2);
  feedbackMsg = 'Lead snoozed. Next review pushed by 2 days to ' + nextActionDue + '.';
} else if (action === 'lost') {
  newStage = 'Lost';
  nextActionDue = '';
  feedbackMsg = 'Lead marked as Disqualified / Lost.';
}

const responseHtml = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Mercian Lead Action Confirmed</title><style>body { font-family: -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif; background: #0b132b; color: #f8fafc; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; } .card { background: #1c2541; padding: 2rem; border-radius: 12px; max-width: 480px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); border: 1px solid #3a506b; text-align: center; } .badge { display: inline-block; padding: 0.25rem 0.75rem; background: #06d6a0; color: #0b132b; font-weight: bold; border-radius: 9999px; margin-bottom: 1rem; } h2 { margin: 0 0 0.5rem 0; color: #ffffff; } p { color: #cbd5e1; line-height: 1.5; } .details { background: #0b132b; padding: 1rem; border-radius: 8px; margin: 1.5rem 0; text-align: left; font-size: 0.9rem; }</style></head><body><div class="card"><div class="badge">ACTION LOGGED</div><h2>Lead ' + leadId + ' Updated</h2><p>' + feedbackMsg + '</p><div class="details"><div><strong>Previous Stage:</strong> ' + currentStage + '</div><div><strong>New Stage:</strong> ' + newStage + '</div>' + (nextActionDue ? '<div><strong>Next Action Due:</strong> ' + nextActionDue + '</div>' : '') + '</div><p style="font-size: 0.8rem; color: #94a3b8;">You can now close this tab and return to WhatsApp.</p></div></body></html>';

return [{
  json: {
    lead_id: leadId,
    business_name: businessName,
    phone: phone,
    action: action,
    previous_stage: currentStage,
    new_stage: newStage,
    new_status: (newStage === 'Lost' ? 'Lost' : (newStage === 'Sourced' ? 'New' : 'Contacted')),
    next_action_due: nextActionDue,
    response_html: responseHtml
  }
}];
